import subprocess
from ipaddress import IPv4Network

def task_func(ip_range):
    """Ping every host in an IPv4 network and return their active status."""
    import platform

    if isinstance(ip_range, IPv4Network):
        network = ip_range
    else:
        ip_range_str = str(ip_range)
        if "/" not in ip_range_str:
            ip_range_str = f"{ip_range_str}/32"
        network = IPv4Network(ip_range_str, strict=False)

    is_windows = platform.system().lower().startswith("win")
    ping_base = ["ping", "-n", "1"] if is_windows else ["ping", "-c", "1"]

    active_map = {}
    for ip in network.hosts():
        try:
            completed = subprocess.run(
                ping_base + [str(ip)],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                check=False,
                timeout=2,
            )
            active_map[str(ip)] = completed.returncode == 0
        except subprocess.TimeoutExpired:
            active_map[str(ip)] = False

    return active_map
